/**
 * The full view of one entity (`design/archetypes/detail-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/detail-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'

import { claimSlot, resolveSlot, scope, type Defaults } from '@polymorph/solid'
import styles from '@polymorph/recipes/archetypes/detail-page.module.css'
import Button from '../controls/Button'

export interface DetailPageProps {
  /**
   * Header actions under PageHeader's law: at most one solid button, and destructive actions in
   * a Menu.
   */
  actions?: JSX.Element
  /**
   * Stat and meta Cards, and when omitted the body is one column.
   */
  aside?: JSX.Element
  backLabel: string
  /**
   * The plain body, omitted when `tabs` provides it.
   */
  children?: JSX.Element
  /**
   * The identity row, such as Badges, an Avatar and timestamps.
   */
  meta?: JSX.Element
  onBack: () => void
  /**
   * Keeps the aside in view while the main column scrolls, at the widths where it is beside the
   * main column. It is never taller than the visible box and scrolls inside itself when it is
   * longer. Default `false`: the aside scrolls with the page.
   */
  stickyAside?: boolean
  /**
   * A full-width `Tabs` as the tabbed body. Use either `tabs` or `children`, not both. A Tabs
   * renders its own panels, so a page with both would show the tab content and then the children
   * below it.
   */
  tabs?: JSX.Element
  /**
   * The entity's name, rendered as the page's `<h1>`.
   */
  title: string
  /**
   * An InlineEdit of the entity's name, drawn beside the `<h1>` as PageHeader draws one, with
   * `title` as its `value` and `size="lg"`. The page hands it `valueHidden`. The app gives it
   * its label, its handlers and, for a save that waits for a server, `editing`, `pending` and
   * `error`.
   */
  titleEdit?: JSX.Element
}

/** The full view of one entity. */
export default function DetailPage(given: DetailPageProps): JSX.Element {
  const props = mergeProps(
    { stickyAside: false } as Defaults<DetailPageProps, 'stickyAside'>,
    claimSlot(given),
  )
  return scope(() => {
    const actionsSlot = resolveSlot(() => props.actions)
    const asideSlot = resolveSlot(() => props.aside)
    const childrenSlot = resolveSlot(() => props.children)
    const metaSlot = resolveSlot(() => props.meta)
    const titleEditSlot = resolveSlot(
      () => props.titleEdit,
      () => ({ valueHidden: true }),
    )
    return (
      <div class={styles.page} data-member="detail-page">
        {/* back */}
        <div class={styles.back}>
          <Button
            variant="ghost"
            tone="neutral"
            size="sm"
            icon="back"
            label={props.backLabel}
            onClick={() => props.onBack?.()}
          />
        </div>
        {/* header */}
        <div class={styles.header}>
          {/* identity */}
          <div class={styles.identity}>
            {titleEditSlot.filled() ? (
              <div class={styles.titleRow}>
                {/* title */}
                <h1 class={styles.title}>{props.title}</h1>
                {/* titleEdit */}
                <div class={styles.titleEdit}>{titleEditSlot()}</div>
              </div>
            ) : (
              <h1 class={styles.title}>{props.title}</h1>
            )}
            {metaSlot.filled() ? <div class={styles.meta}>{metaSlot()}</div> : null}
          </div>
          {actionsSlot.filled() ? <div class={styles.actions}>{actionsSlot()}</div> : null}
        </div>
        {props.tabs}
        {childrenSlot.filled() || asideSlot.filled() ? (
          <div
            class={styles.body}
            data-aside={asideSlot.filled() ? '' : undefined}
            data-sticky-aside={asideSlot.filled() && props.stickyAside ? '' : undefined}
          >
            {/* main */}
            <div class={styles.main}>{childrenSlot()}</div>
            {asideSlot.filled() ? <div class={styles.aside}>{asideSlot()}</div> : null}
          </div>
        ) : null}
      </div>
    )
  })
}
